  return `<div class="multi-picker" data-quote-picker="${key}"><button type="button" class="picker-trigger" data-picker-trigger aria-expanded="false"><span>${selected.length ? selected.map(esc).join('、') : title}</span><i>⌄</i></button><div class="picker-menu" data-picker-menu hidden><div class="picker-tools"><input type="search" data-picker-search placeholder="${t('search')}"><span class="picker-actions"><button type="button" class="text-action select-all-picker">${t('selectAll')}</button><button type="button" class="text-action clear-picker">${t('clear')}</button></span></div><div class="picker-options">${values.map(value=>{const custom=customByValue.get(value);return `<div class="picker-option" data-option="${encodeURIComponent(value)}"><label><input type="checkbox" value="${esc(value)}" ${selected.includes(value)?'checked':''}><b>${esc(value)}</b></label>${custom&&user.role==='brand'?`<span><button type="button" class="option-icon" title="${t('edit')}" onclick="editQuoteOption(${custom.id},decodeURIComponent('${encodeURIComponent(value)}'),'${type}')">✎</button><button type="button" class="option-icon danger" title="${t('delete')}" onclick="deleteQuoteOption(${custom.id})">×</button></span>`:''}</div>`;}).join('') || `<small class="picker-empty">${t('noOptions')}</small>`}</div>${user.role==='brand'?`<button type="button" class="text-action add-picker-item" data-type="${type}">+ ${t('add')} ${title}</button>`:''}</div></div>`;
