function trendChart(data) {
  if (!data.length) return `<div class="empty chart-empty">${t('noChart')}</div>`;
  const byProduct = Object.entries(data.reduce((all,item) => ((all[item.product_name] ||= []).push(item),all),{}));
  const allPrices = data.map(quoteCnyPrice); const min = Math.min(...allPrices), max = Math.max(...allPrices); const pad = Math.max((max - min) * .1, max * .03, 1); const yMin = Math.max(0, min-pad), yMax=max+pad, span=yMax-yMin || 1;
  const dates = uniqueSorted(data.map(item=>String(item.quoted_at).slice(0,10))).sort(); const x = date => 13 + (dates.indexOf(String(date).slice(0,10)) / Math.max(1, dates.length-1)) * 82; const y = price => 82 - ((Number(price)-yMin)/span)*66;
  const grid = Array.from({length:5},(_,i)=>{const value=yMin+(span*i/4), py=y(value);return `<g><line x1="13" y1="${py}" x2="95" y2="${py}" class="chart-grid"/><text x="11" y="${py+2}" text-anchor="end">${value.toFixed(2)}</text></g>`;}).join('');
  const lines = byProduct.map(([product,items],index)=>{const color=quoteColors[index%quoteColors.length], ordered=items.slice().sort((a,b)=>new Date(a.quoted_at)-new Date(b.quoted_at)); const points=ordered.map(item=>`${x(item.quoted_at)},${y(quoteCnyPrice(item))}`).join(' ');return `<g><polyline points="${points}" fill="none" stroke="${color}" stroke-width=".8" vector-effect="non-scaling-stroke"/>${ordered.map(item=>`<circle cx="${x(item.quoted_at)}" cy="${y(quoteCnyPrice(item))}" r="1.3" fill="${color}"><title>${esc(`${fmtDay(item.quoted_at)} | ${item.factory_name} | ${quoteCnyMoney(item)} | MOQ ${item.moq || '-'}`)}</title></circle><text class="point-label" x="${x(item.quoted_at)}" y="${y(quoteCnyPrice(item))-3}">${quoteCnyPrice(item).toFixed(2)}</text>`).join('')}</g>`;}).join('');
  return `<div class="trend-wrap"><svg class="quote-chart quote-trend" viewBox="0 0 100 100" role="img" aria-label="${t('trend')}">${grid}<line x1="13" y1="82" x2="95" y2="82" class="chart-axis"/><line x1="13" y1="16" x2="13" y2="82" class="chart-axis"/>${lines}${dates.map((date,i)=>`<text x="${13+(i/Math.max(1,dates.length-1))*82}" y="91" text-anchor="middle">${date.slice(5)}</text>`).join('')}<text x="54" y="99" text-anchor="middle">${t('priceDate')}</text><text x="3" y="50" transform="rotate(-90 3 50)" text-anchor="middle">${t('priceCny')}</text></svg><div class="chart-legend">${byProduct.map(([product],i)=>`<span><i style="background:${quoteColors[i%quoteColors.length]}"></i>${esc(product)}</span>`).join('')}</div></div>`;
}
function comparisonChart(data) {
  const groups = Object.entries(data.reduce((all,item) => ((all[item.product_name] ||= []).push(item),all),{}));
  if (!groups.length) return `<p class="empty">${t('noChart')}</p>`;
  return groups.map(([product,items])=>{const latest=Object.values(items.reduce((all,item)=>{const old=all[item.factory_name];if(!old||new Date(old.quoted_at)<=new Date(item.quoted_at))all[item.factory_name]=item;return all;},{}));const low=Math.min(...latest.map(quoteCnyPrice)),high=Math.max(...latest.map(quoteCnyPrice)),max=Math.max(high,1),lowItem=latest.find(item=>quoteCnyPrice(item)===low);const delta=high-low;return `<div class="comparison-group"><div class="comparison-summary"><b>${esc(product)}</b><span>${t('latest')} ${esc(lowItem.factory_name)} ${quoteCnyMoney(lowItem)}，${t('spread')} CNY ${delta.toFixed(2)}（${low ? `+${(delta/low*100).toFixed(1)}` : '0.0'}%）</span></div><div class="vertical-bars">${latest.map(item=>{const price=quoteCnyPrice(item),kind=price===low?'lowest':price===high&&high!==low?'highest':'normal';return `<div class="bar-item ${kind}"><b>${quoteCnyMoney(item)}</b><i style="height:${Math.max(10,price/max*145)}px"></i><span>${esc(item.factory_name)}</span></div>`;}).join('')}</div></div>`;}).join('');
}
const refreshPickerSummary = picker => { const key=picker.dataset.quotePicker, title=t(key==='products'?'product':'factory');picker.querySelector('[data-picker-trigger] span').textContent=quoteState[key].length?quoteState[key].join('、'):title; };
